def _tabela_rich\(serie, tipo="valor"\):
    if not serie:
        return ""

    def _parse\(p\):
        try:
            return 2000 + int\(p[2:]\), int\(p[0]\)
        except Exception:
            return None, None

    def _fv\(v\):
        if v is None: return "─"
        neg = v < 0; av = abs\(v\)
        if   av >= 100e9: s = f"{av/1e9:.0f}B"
        elif av >= 10e9:  s = f"{av/1e9:.1f}B"
        elif av >= 1e9:   s = f"{av/1e9:.2f}B"
        elif av >= 100e6: s = f"{av/1e6:.0f}M"
        elif av >= 10e6:  s = f"{av/1e6:.1f}M"
        elif av >= 1e6:   s = f"{av/1e6:.2f}M"
        else:             s = f"{av:.0f}"
        return f"-{s}" if neg else s

    def _fm\(v\):  return "─" if v is None else f"{v:.1f}%"
    def _fpct\(v\):
        if v is None: return "─"
        return f"{'↑' if v >= 0 else '↓'}{abs\(v\):.0f}%"
    def _fpp\(v\):
        if v is None: return "─"
        return f"{'↑' if v >= 0 else '↓'}{abs\(v\):.1f}p"

    fval   = _fm   if tipo == "margem" else _fv
    fdelta = _fpp  if tipo == "margem" else _fpct

    grade = {}
    for x in serie:
        a, q = _parse\(x["periodo"]\)
        if a and q: grade[\(a, q\)] = x["valor"]
    if not grade: return ""

    anos = sorted\({a for a, _ in grade}\)[-2:]
    qs   = [1, 2, 3, 4]

    def _tot\(ano\):
        vs = [grade[\(ano, q\)] for q in qs if \(ano, q\) in grade]
        if not vs: return None
        return sum\(vs\) / len\(vs\) if tipo == "margem" else sum\(vs\)

    rows = {ano: [fval\(grade.get\(\(ano, q\)\)\) for q in qs] for ano in anos}
    tots = {ano: _tot\(ano\) for ano in anos}

    ano_r = anos[-1]; qoq = []; prev = None
    for q in qs:
        v = grade.get\(\(ano_r, q\)\)
        if v is None: qoq.append\("─"\)
        elif prev is None: qoq.append\("base"\); prev = v
        else:
            if tipo == "margem": qoq.append\(_fpp\(v - prev\)\)
            elif prev != 0: qoq.append\(_fpct\(\(v - prev\) / abs\(prev\) * 100\)\)
            else: qoq.append\("─"\)
            prev = v

    yoy = []
    if len\(anos\) == 2:
        ano_a = anos[0]
        for q in qs:
            va = grade.get\(\(ano_a, q\)\); vr = grade.get\(\(ano_r, q\)\)
            if va is None or vr is None: yoy.append\("─"\)
            elif tipo == "margem": yoy.append\(_fpp\(vr - va\)\)
            elif va != 0: yoy.append\(_fpct\(\(vr - va\) / abs\(va\) * 100\)\)
            else: yoy.append\("─"\)

    yoy_tot = ""
    if len\(anos\) == 2:
        qs_r  = {q for q in qs if \(ano_r, q\) in grade}
        t_r   = tots.get\(ano_r\)
        vs_as = [grade[\(anos[0], q\)] for q in qs if q in qs_r and \(anos[0], q\) in grade]
        if t_r is not None and vs_as:
            t_as = sum\(vs_as\)/len\(vs_as\) if tipo == "margem" else sum\(vs_as\)
            if t_as != 0:
                yoy_tot = \(" " + _fpp\(t_r - t_as\) if tipo == "margem"
                           else " " + _fpct\(\(t_r - t_as\) / abs\(t_as\) * 100\)\)

    hdr = ["1T", "2T", "3T", "4T"]
    all_for_w = [hdr, qoq, *rows.values\(\)]
    if yoy: all_for_w.append\(yoy\)
    col_w = [max\(len\(r[i]\) for r in all_for_w\) + 1 for i in range\(4\)]

    def _row\(label, vals, sufixo=""\):
        cells = " ".join\(v.ljust\(c\) for v, c in zip\(vals, col_w\)\)
        return f"{label:<4}{cells}{sufixo}".rstrip\(\)

    def _suf\(ano\):
        t = tots.get\(ano\); return "" if t is None else f" {fval\(t\)}"

    linhas = [_row\("    ", hdr\)]
    for ano in anos:
        linhas.append\(_row\(f"'{str\(ano\)[2:]}:", rows[ano], _suf\(ano\)\)\)
    linhas.append\(_row\("QoQ ", qoq\)\)
    if yoy: linhas.append\(_row\("YoY ", yoy, yoy_tot\)\)
    return nl.join\(linhas\)

